quests[7667] = { title = "Materielle Unterstützung", description = "$n, es gibt da eine dringliche Angelegenheit und ich hoffe, dass Ihr mir dabei helfen könnt... im materiellen und geistigen Sinne. Lasst mich bitte erklären.\n\nTief in Scholomance in Lordaeron gibt es ein Gewölbe, das das Große Ossuarium genannt wird. Ich muss eine Vorrichtung fertigstellen, die die Schatten dieses entsetzlichen Raums durchbohren kann. Um zu beenden, womit ich begonnen habe, brauche ich zwei Diamanten: einen azerothischen und einen makellosen schwarzen Diamanten. Dies sind keine gewöhnlichen Objekte, ich weiß - aber ich verfüge nun einmal nicht selbst über die entsprechenden Mittel.\n\nKönntet Ihr mir jeweils einen von beiden beschaffen?", objectives = "Wenn Ihr Sagorne Gratläufer im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothischen und einen makellosen schwarzen Diamanten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
