quests[7815] = { title = "Schnappkiefer, Alter!", description = "Lass dich ja nicht von ihren großen Augen täuschen, Alter! Die Schnappkiefer da sind ne Bedrohung. Ich kann nicht mal für fünf Minuten angeln, ohne dass einer von diesen überdimensionalen Fisch-Staubsaugern mir meinen Köder klaut.\n\nTut mir und den Leuten von Revantusk einen Gefallen und bringt sie um, Alter.\n\nBringt sie alle um!", objectives = "Katoom, der Angler aus Revantusk im Hinterland möchte, dass Ihr 15 Salzwasserschnappkiefer-Schildkröten tötet. Kehrt zu Ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7816] = { title = "Gammerita, Alter!", description = "Yo! Da is ne Schildkröte da draußen, die nicht wie die anderen is'. Das is' die Gammerita,  Anführerin der Salzwasserschnappkiefer, 'ne richtig fiese Diebin!\n\nAlter, die hat mir meinen besten Köder geklaut. Einfach so abgebissen, hatse den! Seitdem beißen die Fisch nichmehr so an wie vorher.\n\nFinde Gammerita und hol' mir den Köder aus ihrem Bauch.", objectives = "Katoom, der Angler aus Revantusk im Hinterland möchte, dass Ihr Gammerita  tötet und Katooms besten Köder aus ihrem Kadaver holt.\n\nKatoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
