quests[7839] = { title = "Schläger der Vilebranch", description = "Der Vilebranchabschaum ist in unser Dorf eingedrungen und hat mein Werkzeug gestohlen! Ich habe zwar Ersatz, aber das Set, das sie mir geraubt haben, war das Geschenk eines gutherzigen Gnoms, der mir als junger Orc das Leben gerettet hat.\n\nIch möchte dieses Werkzeug wieder haben, $N - es bedeutet mir ungeheuer viel.\n\nMarkhor berichtete, dass die Wekzeuge nahe der Tempel von Agol'watha und Shaol'watha gesichtet wurden.\n\nDiese Tempel liegen im Nordosten des Hinterlands.\n\nFindet meine Werkzeuge!", objectives = "Schmied Slagtree aus Revantusk im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt.\n\nIhr erinnert Euch an Schmied Slagtrees Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Vilebranch zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch Skulk Rock absuchen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7840] = { title = "Lards vergessene Brotzeit", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Vilebranch Lard mit großem Stock geschlagen hat. Lard zurück nach Revantusk gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", objectives = "Lard aus Revantusk im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Vilebranch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7841] = { title = "Eine Botschaft an die Wildhämmer", description = "Die Wildhammer fangen Geschäfte mit unseren Feinden an, Mann, schmieden neue Bündnisse. Diesmal sind es die Hochelfen, Mann.\n\n<Otho spuckt.>\n\nWir werden diesen Wildhammer-Zwergen wohl 'ne Botschaft überbringen müssen - 'ne Botschaft geschrieben mit dem Blut unserer Feinde. Tötet alle Hochtalelfen, alle die Euch über den Weg laufen, klar? Un' lasst ihre Leichen als Warnung zurück.\n\nVerscherzt es Euch niemals mit den Trollen!", objectives = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr 15 Hochtalkundschafterinnen, 15 Hochtalspäher, 15 Hochtalschützen und 15 Hochtalwaldläuferinnen tötet. Kehrt nach vollendeten Taten zu ihm zurück.\n\nIhr findet die Hochtalelfen bei der Quel'Danil-Hütte im Nordwesten des Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7842] = { title = "Eine weitere Botschaft an die Wildhämmer", description = "Man sagt, dass die Wildhammer den Greifen so nahe stehen wie die Trolle ihren Gefährten. Widerlich, aber wir können das zu unserem Vorteil nutzen, Mann. Wir senden ihnen eine weitere Botschaft.\n\nTötet alle Greifen, die Ihr im Hinterland seht und sammelt ihre Federn ein. Daraus machen wir dann die letzte Botschaft.", objectives = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr ihm 10 lange elegante Federn von Greifen besorgt, die das Hinterland bewohnen. Kehrt mit den Federn zu ihm zurück.\n\nEs ist bekannt, dass Greifen überall im Hinterland zu finden sind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7843] = { title = "Die letzte Botschaft an die Wildhämmer", description = "<Otho überreicht Euch einen langen, blutverschmierten Speer, den mehrere Greifenfedern umhüllen.>\n\nNehmt den hier, Mann. Geht damit zum Aerie Peak, zum toten Stadtzentrum beim Brunnen. Platziert ihn dort! Rammt ihn richtig in den Boden und zeigt diesen Zwergen, dass die Trolle es ernst meinen! Kommt danach zu mir zurück... hoffentlich noch in einem Stück.", objectives = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr zum Aerie Peak im Westen des Hinterlands reist und die letzte Botschaft an die Wildhammer beim Brunnen im Stadtzentrum platziert. Kehrt nach Vollendung der Aufgabe zu ihm zurück.\n\nHütet Euch vor zornigen Wildhammer-Zwergen und niederträchtigen Mitgliedern der Allianz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7844] = { title = "Kannibalistische Vettern", description = "Drei verschiedene Troll-Stämme bewohnen das Hinterland, $N. Soviel zu den Gemeinsamkeiten der Stämme: Wir sind alle Trolle und wir leben im Hinterland.\n\nDie Vilebranch sind eine verkommene Bande, die sich an anderen Trollen und Humanoiden nährt.\n\nWäre Zul'jin hier, hätte er sie alle mit einem einzigen Faustschlag niedergeschmettert - ach, Zul'jin ist noch immer nicht zurückgekehrt und wir sind unseren eigenen Mitteln überlassen.\n\nEs liegt nun an Euch diese Gegend zu säubern!", objectives = "Mystikerin Yayo'jin aus Revantusk im Hinterland möchte, dass Ihr 30 Skalpierer der Vilebranch und 15 Sterndeuter der Vilebranch tötet. Kehrt nach Vollendung dieser Aufgabe zu ihr zurück.\n\nYayo'jin deutete an, dass man diese Trolle nahe der Tempel von Shaol'watha und Agol'watha finden könnte. Sie liegen im Nordosten des Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7845] = { title = "Die Entführung des Älteren Torntusk", description = "Mein Gefährte wurde von den wilden Vilebranch bei einem dreisten Überfall um Mitternacht verschleppt. Unsere Spione haben mir berichtet, dass er noch am Leben ist und hoch oben in Jintha'Alor gefangen gehalten wird. Man sagt, dass die üble Priesterin Hexx ihn als Opfer für den gesichtslosen Blutgott Hakkar vorbereiten lässt.\n\nIhr müsst ihn retten, $N! Unser Dorf könnte einen so großen Verlust nicht verschmerzen.", objectives = "Primal Torntusk aus Raventusk im Hinterland möchte, dass Ihr ihren Gefährten, den Älteren Torntusk, aus Jintha'Alor befreit.\n\nMan sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Vilebranch im Süden des Hinterlands.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7846] = { title = "Erlangt den Schlüssel!", description = "Der Schlüssel zu meinen Fesseln ist im Besitz von Hitah'ya der Bewahrerin. Sie hält sich in der nahegelegenen Höhle auf. Seid vorsichtig, $C, sie wird äußerst gut bewacht.\n\nTötet sie und bringt dann den Schlüssel zurück, um meine Fesseln zu öffnen. Erst dann werde ich frei und in der Lage sein, nach Hause zurückzukehren.", objectives = "Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Älteren Torn'tusk zurück, wenn Ihr den Schlüssel habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7847] = { title = "Rückkehr zu Primal Torntusk", description = "Kehrt zu meiner Gefährtin Primal Torntusk in Revantusk zurück. Richtet ihr aus, dass ich heimkehren werde! Sie wird Euch sicherlich belohnen.", objectives = "Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Primal Torntusk in Revantusk die Neuigkeit von seiner Befreiung überbringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7848] = { title = "Abstimmung mit dem Kern", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, $R. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Blackrock führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Blackrocktiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.", objectives = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7849] = { title = "Die getrennten Brüder", description = "Wie viele in unserem Dorf, habe auch ich einen Nahestehenden verloren. Ach, es war mein Zwillingsbruder Malkhor - er wurde beim selben Überfall wie Torntusks Gefährte von den Vilebranch verschleppt.\n\nDas Schicksal sollte ihn traurigerweise nicht vom Tod verschonen und er wurde schnell und brutal hingerichtet. Seine Überreste wurden an die Brühschlammer und Wölfe der Vilebranch verfüttert.\n\nWir können zwar nicht mehr sein Leben retten, aber es ist noch nicht zu spät, um seine Seele zu befreien. Bergt seine Überreste, $N.", objectives = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück.\n\nMarkhor erwähnte, dass die Überreste seines Bruders an die Brühschlammer und Wölfe der Vilebranch verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Brühschlammern gibt, sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7850] = { title = "Dunkle Gefäße", description = "Die Vilebranch kämpfen mit übernatürlicher Wildheit. Dies liegt an der elenden Magie, die von der üblen Priesterin Hexx gewirkt wird.\n\nIhr werdet in ganz Jintha'Alor dunkle Gefäße mit besudeltem Blut finden. Die Gefäße verstrahlen die elende Magie des gesichtslosen Blutgottes, verleihen den Vilebranch Macht und treiben sie zusätzlich in den Wahnsinn.\n\nStehlt diese Gefäße und bringt sie zu mir, damit ich sie von der Besudelung reinigen und letztendlich die Gewalt des Blutgottes zerschlagen kann.", objectives = "Primal Torntusk aus Revantusk im Hinterland möchte, dass Ihr Euch 10 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Primal Torntusk zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7861] = { title = "GESUCHT: Üble Priesterin Hexx und ihre Diener", description = "Der üblen Priesterin Hexx und ihren Dienern soll im Namen von Primal Torntusk Gerechtigkeit widerfahren!\n\nWer auch immer die üble Priesterin Hexx und alle ihre Aman'zasiwachen vernichten möge, soll eine bedeutende Entlohnung erhalten.", objectives = "Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 20 Aman'zasiwachen der Vilebranch zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Primal Torntusk aus Revantusk im Hinterland.\n\nDie üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7862] = { title = "Offener Posten: Wachbefehlshaber von Revantusk", description = "Mit dem Verlust von Malkhor ist auch wieder der Posten des Wachbefehlshabers von Revantusk unbesetzt. Sollte es Euch interessieren Befehlshaber der Wachen von Revantusk zu werden, so erfüllt die folgenden Aufgaben und reicht Eure Bewerbung bei Primal Torntusk ein:\n\nRottet die Berserker der Vilebranch aus.\n\nRottet die Schattenjäger der Vilebranch aus.\n\nRottet die Bluttrinker der Vilebranch aus.\n\nRottet die Seelenfresser der Vilebranch aus.", objectives = "Ihr wurdet mit der Vernichtung von 20 Berserkern der Vilebranch, 20 Schattenjägern der Vilebranch, 20 Bluttrinkern der Vilebranch und 20 Seelenfressern der Vilebranch beauftragt.\n\nKehrt nach Beendigung dieser Aufgabe zu Primal Torntusk aus Revantusk im Hinterland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
