quests[7944] = { title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch in den Höhlen des Wehklagens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr eine Höhle im Südwesten von Crossroads im Brachland. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch gewundene Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Höhlen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.", objectives = "Reist zu den Höhlen des Wehklagens im Brachland und sucht nach Eurem Schicksal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[7945] = { title = "Euer Schicksal erwartet Euch...", description = "\"Euer Schicksal erwartet Euch außerhalb des Bleichmähnenfelsens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr den Bleichmähnenfels von Mulgore. Beim Fokussieren auf dieses Bild seht Ihr einen Baumstumpf in der Nähe des Höhleneingangs.", objectives = "Reist zum Bleichmähnenfels in Mulgore und sucht nach Eurem Schicksal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
