quests[8053] = { title = "Symbole der Macht: Die Armschützer des Freidenkers", description = "Ihr seid ungläubig. Ungläubige haben einen Platz in unserem Stamm. Ungläubige sind Freidenker der Zandalari. Freidenker fürchten sich nicht vor Unterdrückung und sterben für das, woran sie glauben. Wir wissen, dass Ihr für das, woran Ihr glaubt, sterben würdet. Dies verdient unsere Anerkennung. Ihr dürft Euch uns auch weiterhin als würdig erweisen.\n\nWir brauchen die Symbole der Macht. Geht nach Zul'Gurub. Tötet die Diener Hakkars. Sobald Ihr habt, wonach ich verlange, kommt zu mir zurück. Strebt nach der ersten Kampfausrüstung eines Zandalarifreidenkers.\n\nUnd nun geht.", objectives = "Bringt urzeitliche Hakkaribindungen zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8054] = { title = "Symbole der Macht: Der Gürtel des Freidenkers", description = "Eure Überzeugungen sind uns fremd, $g Ungläubiger:Ungläubige;. Die Uralten von Zandalar wurden einst als Heiden gebrandmarkt. Dies war in der Zeit als das Imperium der Gurubashi noch mächtig war. Ungläubige wagten es, den Priester Hakkars herauszufordern. Sie wurden daraufhin gejagt und wie Ungeziefer vernichtet. Diese Ungläubigen wankten niemals in ihrem Kampf gegen den Blutgott. Wir wissen den Preis, den sie dafür bezahlen mussten, zu schätzen. Sie sind die Freidenker.\n\nMacht den Dienern Hakkars in Zul'Gurub den Garaus. Bringt mir das Symbol der Macht, nach denen ich verlange. Erfolgreiche Taten sollen großzügig belohnt werden.\n\nUnd nun geht.", objectives = "Bringt einen urzeitlichen Hakkarischal zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8055] = { title = "Symbole der Macht: Die Brustplatte des Freidenkers", description = "Im Stamm verleiht die Kampfausrüstung Macht. Die Freidenker sind auf diese Weise geehrt. Sie sind Zeloten. Sie tränken ihre Brustplatten mit mächtigem Mojo. Wenn ihr Glaube im Angesicht des Feindes zu wanken beginnt, so werden ihre Brustplatten dennoch standhalten.\n\nIhr müsst bei uns einen respektvollen Ruf genießen, um solch eine Brustplatte zu besitzen. Geht nach Zul'Gurub. Ihr müsst das von mir benötigte Symbol der Macht beschaffen. Entwendet es den Narren auf schmerzlichste Art und Weise. Bringt es zu mir. Beweist Euch ein für alle Mal als Freidenker würdig.", objectives = "Bringt einen urzeitlichen Hakkariwappenrock zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8056] = { title = "Symbole der Macht: Die Armschienen des Weissagers", description = "Die Weissager unseres Stammes werden für ihre Gaben der göttlichen Sicht respektiert, ja wirklich. Sie sind nicht etwa eine Art Hexendoktor, nein, sie verbringen ihre Zeit mit dem Beschwören von Knochen oder dem Lesen von Blättern der Einsicht, und nicht mit dem Verhexen anderer. Als Schamane wisst Ihr bereits etwas über die Macht der Weissagung; wir Zandalari würdigen die Einsicht, die unserem Stamm gegeben wird.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Helft Ihr uns, werde ich Euch Armschienen geben, die unsere Weissager mehr als alles andere verehren!", objectives = "Bringt urzeitliche Hakkariarmsplinte zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8057] = { title = "Symbole der Macht: Die Haruspexarmschienen", description = "Ein Haruspex ist ein wichtiges Mitglied in unserem Stamm, ihr tut gut daran auf ihr Omen zu hören. Mittels spiritueller Vereinigung mit den Tieren und deren Opferung, falls nötig, schenken sie uns göttliche Leitung. In der Vergangenheit verschaffte uns die Einsicht und Weisheit der Haruspex einen Vorteil in den Kämpfen gegen die zersplitterten Stämme der Gurubashi.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit Armschienen belohnen, die selbst ein Haruspex der Zandalari begehrt.", objectives = "Bringt eine urzeitliche Hakkaristütze zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8058] = { title = "Symbole der Macht: Die Armschützer des Vollstreckers", description = "Rache ist Macht. Der Vollstrecker der Zandalari ist solch eine Macht. Unser Stamm hat viele Feinde. Der Vollstrecker fordert Vergeltung von ihnen ein. Kein Verbrechen gegen uns bleibt unbestraft und der Vollstrecker sorgt für diese Bestrafung. Unsere Feinde fürchten sich vor unserer Rache. Das sollen sie auch, und sie werden es auch für immer tun.\n\nWerdet einer unserer Vollstrecker. Sucht nach den Symbolen der Macht in Zul'Gurub. Tötet die Diener Hakkars und sorgt im Namen unseres Stammes für Vergeltung. Ihr werdet belohnt werden.", objectives = "Bringt urzeitliche Hakkariarmsplinte zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8059] = { title = "Symbole der Macht: Die Handlappen des Besessenen", description = "Hexenmeister begeben sich bei ihrem Umgang mit Dämonen auf ein gefährliches Terrain, unsere Besessenen gehen jedoch noch einen Schritt weiter. Mithilfe eines uralten, arkanen Rituals erlauben sie es einem Dämon, in ihre Gestalt zu schlüpfen. Anstelle von ihm besessen zu werden, versklaven sie den Dämon von innen heraus und absorbieren die Macht des Ungetüms für ihre eigenen Zwecke. Es ist eine Fähigkeit, die nur wenige zu meistern verstehen.\n\nDamit Ihr von der Macht der Besessenen lernen könnt, müsst Ihr mir ein Symbol der Macht von Zul'Gurub beschaffen. Geht und bringt mir, wonach ich verlange.", objectives = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8060] = { title = "Symbole der Macht: Die Handlappen des Illusionisten", description = "Magier sind in unserem Stamm als Illusionisten bekannt. Sie setzen bei ihren Beschwörungen mächtiges Mojo ein, bringen die Feinde des Stamms oft durcheinander und machen sie konfus!\n\n<Al'tabim lacht gehässig.>\n\nEs ist schon ein ziemliches Spektakel, wenn man einem mächtigen Illusionisten bei der Arbeit zusieht und beobachtet wie er unsere Feinde mithilfe ihres eigenen Wahnsinns in die Knie zwingt!\n\nWenn Ihr mehr über den Weg unserer Illusionisten lernen möchtet, dann geht nach Zul'Gurub und bringt ein bestimmtes Symbol der Macht zu mir zurück. Ich werde Euch dafür mit Handlappen belohnen, die unsere Illusionisten zum Weben ihrer Zauber verwenden.", objectives = "Bringt urzeitliche Hakkaribindungen zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8061] = { title = "Symbole der Macht: Die Handlappen des Glaubenshüters", description = "Wir Zandalari investieren Macht in diejenigen, die mit der Gewalt des Göttlichen sprechen. Unsere Priester sind mehr als nur Heiler; sie sind auch unsere Hüter des Glaubens. Das Böse kommt von äußeren Bedrohungen, wie zum Beispiel Hakkar, wie auch von innerhalb des Stammes. Unsere Glaubenshüter agieren wie die Richter unter uns, sie schützen uns vor dem gleichen Übel, das bereits die Gurubashi sich selbst hat zerstören lassen.\n\nGeht nach Zul'Gurub und bringt die Symbole der Macht von den Gurubashi zurück. Lernt, was es heißt, ein Glaubenshüter zu sein, und schützt uns vor dem Bösen.", objectives = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8062] = { title = "Symbole der Macht: Die Armschienen des Raubtiers", description = "In den dunklen Zeiten nach dem Fall des Imperiums der Gurubashi setzten die Jäger der Zandalari ihre Tapferkeit ein, um den Lebensunterhalt für den Stamm zu sichern. Man vergleicht sich gerne mit den Jägern unseres Stammes: Das Streben nach der Jagd bedeutet das Einswerden mit der Essenz des Jägers, ja. Eure Jagd in Zul'Gurub wird uns zeigen, in welchem Verhältnis Ihr zu unseren besten Jägern steht.\n\nBringt mir ein Muster der Symbole der Macht aus Zul'Gurub. Ihr werdet damit Eure ersten Schritte tun, die es braucht, um vorletzter Jäger zu werden.", objectives = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Urzeitliche Hakkaribindungen. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8063] = { title = "Symbole der Macht: Die Armschienen des Wildfangs", description = "Die Wildfänge von Zandalar ähneln den Schurken, vertraut sind sie vor allem aber mit dem Wahnsinn... dem Chaos... der Unberechenbarkeit des Lebens. Als unvergesslicher Anblick des Terrors auf dem Schlachtfeld, säten sie in den wilden Zeiten nach Aufsplittung der Stämme Verwirrung und Chaos unter unseren Feinden. Ohne sie, würde es uns heute nicht geben.\n\nBringt mir das gewünschte Symbol der Macht von Zul'Gurub und ich werde Euch mit den so begehrten Armschienen des Wildfangs belohnen. Gebt Euch dem Wahnsinn hin!", objectives = "Bringt urzeitliche Hakkariarmsplinte zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8064] = { title = "Symbole der Macht: Der Haruspexgürtel", description = "Die Zandalari kennen die Wege der Druiden nicht; die Natur soll nach unseren Bedürfnissen geformt werden und nicht umgekehrt. Dennoch gehören die Haruspex zu denen, die am meisten mit der Natur im Einklang leben, und das mit Recht. Den Geist eines Wildtiers zu opfern, bedeutet zu wissen, wie es ist einer von ihnen zu sein. Das ist die wahre Macht der Natur.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit einem mächtigen Gegenstand belohnen: einem Gürtel, wie ihn viele Haruspex der Zandalari verwenden.\n\nStarkes Mojo, ja!", objectives = "Bringt eine urzeitliche Hakkarischärpe zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber außerdem wohlwollend sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8065] = { title = "Symbole der Macht: Die Haruspextunika", description = "Das ultimative Symbol der Macht eines Haruspex ist die Kleidung, die er trägt, $n. Die Tunika symbolisiert die Verbindung zwischen ihnen selbst und der göttlichen Weisheit, nach der sie streben. Oft werden in die Tunika Teile der geopferten Tiere eingewoben, die sie an die Verbundenheit mit deren Talenten erinnern.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so wird Euch eine wie von mir beschriebene Tunika gehören.", objectives = "Bringt einen urzeitlichen Hakkariwappenrock zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber außerdem respektvoll sein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8066] = { title = "Symbole der Macht: Der Gürtel des Raubtiers", description = "Ein Raubtier weiß, wie es sich an seine Beute heranschleicht, ein erfolgreiches Raubtier weiß aber auch, wie es seine Beute schlägt, sobald es zu ihr aufgeschlossen hat. Ihr müsst beides beherrschen, wenn Ihr in Zul'Gurub erfolgreich sein wollt... und wenn Ihr Euch mit den Jägern der Zandalari vergleichen wollt.\n\nBringt mir ein ausgesuchtes Teil der Symbole der Macht aus Zul'Gurub. Meine Belohnung wird die Macht sein, die diese Schmuckstücke enthalten, Eure wird dagegen der Gürtel des Zandalariraubtiers sein, ein Gegenstand, der den Tausch sehr wohl wert ist, glaubt mir.", objectives = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Einen urzeitlichen Hakkarischal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8067] = { title = "Symbole der Macht: Der Mantel des Raubtiers", description = "Wir Zandalari schätzen unsere Kleidung als eine Art Symbol für vollbrachte Taten. Man muss nicht sehen können, was jemand trägt, um zu spüren, was davon ausgeht. Macht geht über die Sicht hinaus. Die Bekleidung von Zandalarijägern ist von dieser Art, und der wohl am meisten verehrte Teil davon ist der Mantel, den sie tragen. Er hilft ihnen ihr Erscheinungsbild zu verschleiern... und ihre Gegenwart dann bekannt zu geben, wenn sie es möchten.\n\nDie Symbole der Macht warten in Zul'Gurub darauf, von Euch zurückerobert zu werden. Bringt mir, wonach ich verlange, und der Mantel des Zandalariraubtiers soll Euer Eigen sein.", objectives = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Eine urzeitliche Aegis der Hakkari. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8068] = { title = "Symbole der Macht: Der Mantel des Illusionisten", description = "Magie ist eine rohe, uralte Kraft, die von denen beherrscht werden muss, die stark genug dafür sind. Mojo ist unser verlängerter Arm dieser Macht; eine der mächtigsten Manipulationen davon ist die Form der Illusion. Wie kann man sich ernsthaft erhoffen einen Feind zu schlagen, der nicht einmal wirklich da ist? Wir Zandalari wissen von dieser Macht und daher wird den Illusionisten eine besondere Stellung in unserem Stamm zuteil.\n\nBeschafft das notwendige Symbol der Macht von Zul'Gurub... dafür werdet Ihr mit dem Wohlwollen unseres Stammes und einem mächtigen Mantel, wie er von unseren besten Illusionisten verwendet wird, belohnt werden!", objectives = "Bringt einen urzeitlichen Hakkarischal zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8069] = { title = "Symbole der Macht: Die Roben des Illusionisten", description = "Im Stamm wird Stellung und Macht durch das ausgezeichnet, was man trägt. Unsere Kleidung wird aus den feinsten Materialien hergestellt und mit Mojo verwoben, mit dessen Hilfe wir uns Macht verleihen. Illusionisten sind keine Ausnahme; man sagt, dass ihre Roben mittels ihres Aussehens die Essenz der Illusion verkörpern. Legenden besagen, dass ihre uralten Roben niemals gleich aussahen.\n\nIch werde Euch die Robe eines Illusionisten geben, $n... aber zuerst müsst Ihr Euch in unserem Stamm Respekt verdienen! Bringt mir ein Symbol der Macht von Zul'Gurub!", objectives = "Bringt einen urzeitlichen Hakkarikosak Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8070] = { title = "Symbole der Macht: Die Bindungen des Glaubenshüters", description = "Kurze Zeit nach dem Fall der Gurubashi wurden wir Zandalari fast endgültig vom Bösen innerhalb unseres Stammes besiegt. Es war zu dieser Zeit, dass die sich Glaubenshüter unter uns erhoben, um den Stamm zu schützen und diejenigen zu verbannen, die unsereins zu zerstören trachteten. Sie erhalten nicht nur den Einklang zwischen uns und den Geistern, sie erhalten auch unsere Leiber.\n\nReist weit nach Zul'Gurub und werdet selbst Zeuge von der Verdorbenheit Hakkars und der Gurubashis. Entringt ihnen die Symbole der Macht, nach denen wir suchen, und Euer Erfolg soll belohnt werden!", objectives = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8071] = { title = "Symbole der Macht: Der Mantel des Glaubenshüters", description = "Alle Glaubenshüter der Zandalari tragen einen bestimmten Mantel, der sie als Beschützer des Stammes auszeichnet. Diese Mäntel werden aus mächtigem Mojo gewoben, das beim Beurteilen derjenigen behilflich ist, die eine Bedrohung für unseren Stamm darstellen. Auch Ihr müsst als Priester Zeit aufwenden, um zu beurteilen, wer würdig ist und wer nicht; ein solcher Mantel wäre zweifellos ein Segen für Euch.\n\nWenn Ihr Hakkars Diener in Zul'Gurub besiegt und mir das benötigte Symbol der Macht besorgt, werde ich Euch im Austausch dafür einen Mantel geben, der unter unseren Glaubenshütern als hoch und heilig gilt.", objectives = "Bringt eine urzeitliche Aegis der Hakkari zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8072] = { title = "Symbole der Macht: Der Mantel des Wildfangs", description = "Khar'vaxal der Irrsinnige war einer der legendären Wildfänge der Zandalari. Legenden zufolge benutze er seinen Mantel, der speziell aus \"Stoff des Wahnsinns\" gewoben wurde, als er den Feinden des Stammes zum ersten Mal gegenübertrat. Seine Gestalt wurde nicht nur von dem Mantel, sondern auch dank der blendenden Geschwindigkeit seiner Zwillingsdolche verschleiert. Heute verehren die Wildfänge ihren Mantel als Zeichen der Stammeszugehörigkeit und der Stellung, die ihnen zusteht.\n\nBringt mir das gewünschte Symbol der Macht und ein derartiger Mantel wird Euch gehören und Eure Feinde in Wahnsinn hüllen.", objectives = "Bringt einen urzeitlichen Hakkarigurt zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8073] = { title = "Symbole der Macht: Die Tunika des Wildfangs", description = "Meine Augen haben mich schon seit langem im Stich gelassen, aber ich trauere ihnen nicht nach. Selbst in einem Stamm wie dem unsrigen, in dem die Kleidung Rang und Bestimmung vermittelt, strahlen die einflussreichsten aller Gewänder eine Macht aus, die für normale Augen nicht sichtbar ist. Die Tunika des Zandalariwildfangs ist keine Ausnahme, sie strahlt die rohe Macht des Chaos und des Wahnsinns aus, die mit ihr kanalisiert werden kann.\n\nDie Symbole der Macht, die ich benötige, befinden sich in Zul'Gurub; bringt mir eines und ich werde Euch mit Eurer eigenen legendären Tunika belohnen... eine, die einem Säer des Wahnsinns gerecht wird.", objectives = "Bringt eine urzeitliche Aegis der Hakkari zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8074] = { title = "Symbole der Macht: Der Gürtel des Weissagers", description = "Die Weissager kennen das Mojo der Elemente, das ist wahr. Sie setzen es ein, um den Stamm zu Ruhm und Ehre zu führen. In den dunklen Zeiten, nachdem das Imperium der Gurubashi sich selbst zersplitterte, führten uns unsere Weissager in den sicheren Hafen der südlichen See. Sie haben uns auch wieder zurück hierher ins Tal geführt, genau ins Herz des Bösen, das in Zul'Gurub schwelt.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch einen Gürtel geben, wie ihn unsere Weissager verwenden, einen mit mächtigem Mojo!", objectives = "Bringt einen urzeitlichen Hakkarigurt zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8075] = { title = "Symbole der Macht: Die Halsberge des Weissagers", description = "Die Weissager der Zandalari tragen einen bestimmten Brustschmuck, der Halsberge genannt wird. Er wird aus feinster Seide und Stoffen zusammengefügt und mit starken Ketten verwoben. Es ist nicht nur ein Symbol für ihre Göttlichkeit, sondern auch für ihre Autorität. Es ist niemals sehr weise den Weg von jemanden zu kreuzen, der sein Leben der Zwiesprache mit den Geistern gewidmet hat...\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch eine der feinsten Halsbergen geben, die sich selbst einer der unsrigen Weissager zu tragen erhofft!", objectives = "Bringt einen urzeitlichen Hakkariwappenrock zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8076] = { title = "Symbole der Macht: Der Mantel des Besessenen", description = "Der Besessene möchte Macht geradewegs verkörpern und nicht nur besitzen. Mehr als ein Besessener hat bereits den Kampf gegen einen Dämonen verloren; die Feinde, die uns bedrohen, besonders in Zul'Gurub, und die Macht, die ein Besessener auf unsere Feinde loslassen kann, sind das Opfer jedoch wert. Unser Überleben hängt von der Zerstörung derer ab, die nach unserem Ende trachten; das hat uns der Fall des Imperiums der Gurubashi gelehrt.\n\nReist nach Zul'Gurub und beschafft uns das von uns benötigte Symbol der Macht. Solltet Ihr dabei Erfolg haben, soll ein wertvoller Gegenstand eines Besessenen Euer Eigen sein.", objectives = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8077] = { title = "Symbole der Macht: Die Roben des Besessenen", description = "Im Stamm ist das ultimative Zeichen für Macht die Kleidung, die im Kampf getragen wird. Die Roben des Besessenen vereinen feinen Runenstoff und verheerend mächtiges Mojo. Man sagt, dass das Aussehen dieser Roben allen Angst einflößt, die sie erblicken... besonders den Dämonen, die der Besessene eventuell beherrschen möchte.\n\nIhr müsst mir von Zul'Gurub ein besonderes Symbol der Macht besorgen. Es wird nicht einfach sein... Euer erfolgreiches Handeln wird Euch jedoch den Besitz einer der besagten Roben sichern.", objectives = "Bringt einen urzeitlichen Hakkarikosak zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8078] = { title = "Symbole der Macht: Der Gürtel des Vollstreckers", description = "Die ultimative Rache wartet innerhalb Zul'Gurubs. Hakkar darf nicht mehr auferstehen. Hakkar hat das Imperium der Gurubashi von innen heraus zerstört. Kein Opfer war ihm dafür zu schade. Die Trolle sind nur noch ein Schatten ihrer glorreichen Zeiten. Ich weiß, dass all dies auf Hakkar beruht.\n\nWerdet der Vollstrecker, zu dem Ihr bestimmt wart. Bringt Zerstörung über die Diener des Bösen herein. Zul'Gurub muss den Rachedurst der Zandalari zu spüren bekommen. Bringt mir ein Symbol der Macht als Beweis. Ihr werdet dafür den Gürtel des Vollstreckers bekommen. Ihr werdet wahre Macht erhalten.\n\nUnd nun geht.", objectives = "Bringt einen urzeitlichen Hakkarigurt zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8079] = { title = "Symbole der Macht: Die Brustplatte des Vollstreckers", description = "Die Brustplatte ist das Symbol der Macht eines Vollstreckers. Sie wird mit mächtigem Mojo geschmiedet. Sie wird nur denen anvertraut, die wir ehren. Es ist das Symbol der Rache der Zandalari.\n\nEin Vollstrecker zu werden, bedeutet ein Rächer zu werden. Beschafft das benötigte Symbol der Macht von Zul'Gurub. Bringt es zu uns. Wir werden uns das von uns gestohlene Mojo zurückholen. Die Diener Hakkars werden bezahlen müssen. Eure Belohnung wird die Brustplatte des Vollstreckers sein.\n\nGeht. Seid unser Rächer, $n.", objectives = "Bringt einen urzeitlichen Hakkarikosak zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8080] = { title = "Die Ressourcen des Arathibeckens", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, $n. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", objectives = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8081] = { title = "Noch mehr Vorratskisten", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, $N. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.", objectives = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Unteroffizier Maclear in der Zuflucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
