quests[8114] = { title = "Kontrolliert vier Stützpunkte", description = "$n, Ihr habt unseren Feinden im Arathibecken den Krieg gebracht und auf dem Schlachtfeld große Ehre erlangt. Ihr habt bewiesen, wie wertvoll Ihr als $C für uns seid, und unseren Feinden gezeigt, dass wir uns ihren Streitkräften gegenüber nicht beugen werden!\n\nDa Ihr Euren Wert unter Beweis gestellt habt, habe ich einen besonders schwierige Auftrag für Euch. Ich möchte, dass Ihr mindestens vier der Stützpunkte im Arathibecken besetzt und haltet. Wenn Euch das gelingt, sichern wir uns nicht nur kritische Ressourcen, sondern zeigen der Horde auch unsere Überlegenheit!\n\nGeht nun, $n, und viel Glück!", objectives = "Betretet das Arathibecken, erobert und kontrolliert gleichzeitig vier Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Lichtmark in der Zuflucht zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[8115] = { title = "Kontrolliert fünf Stützpunkte", description = "$n, es ist ein blutiges Unterfangen um die Ressourcen von Arathor zu kämpfen. Eure Dienste für den Bund von Arathor werden genauso dringend gebraucht, wie sie honoriert werden.\n\nWir haben eine weitere Aufgabe für Euch.\n\nDer Bund möchte einen Schlag gegen die Okkupation der Entweihten im Arathibecken vollbringen. Wir möchten sie von jedem strategischen Punkt des Schlachtfelds vertreiben!\n\nEs wird nicht leicht werden, aber wenn es überhaupt jemand schaffen kann, dann Ihr.", objectives = "Kontrolliert gleichzeitig fünf Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Lichtmark in der Zuflucht zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
